import * as React from 'react';
import * as ExpandableCardPrimitive from '@exhuma/core';
import { cn } from '@/lib/utils';

export interface ExpandableCardProps extends React.ComponentPropsWithoutRef<typeof ExpandableCardPrimitive.ExpandableCard> {
  className?: string;
}

export const ExpandableCard = React.forwardRef<HTMLDivElement, ExpandableCardProps>(
  ({ className, children, ...props }, ref) => (
    <ExpandableCardPrimitive.ExpandableCard
      ref={ref}
      className={cn(
        'relative overflow-hidden rounded-2xl border border-border bg-card p-6 shadow-sm transition-shadow hover:shadow-md cursor-pointer',
        className
      )}
      {...props}
    >
      {children}
    </ExpandableCardPrimitive.ExpandableCard>
  )
);
ExpandableCard.displayName = 'ExpandableCard';

