solid.code:
import { Component, JSX, splitProps } from 'solid-js';
import * as ExpandableCardPrimitive from '@exhuma/core';

export interface ExpandableCardProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const ExpandableCard: Component<ExpandableCardProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <ExpandableCardPrimitive.ExpandableCard
      class={`relative overflow-hidden rounded-2xl border border-border bg-card p-6 shadow-sm transition-shadow hover:shadow-md cursor-pointer ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </ExpandableCardPrimitive.ExpandableCard>
  );
};

