import { ExpandableCard } from '@exhuma/core';

class ExhumaExpandableCardElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-expandable-card');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-expandable-card')) {
  customElements.define('exhuma-expandable-card', ExhumaExpandableCardElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as ExpandableCardPrimitive from '@exhuma/core';

export interface ExpandableCardProps extends ViewProps {
  children?: React.ReactNode;
}

export function ExpandableCard({ style, children, ...props }: ExpandableCardProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

flutter.code:
import 'package:flutter/material.dart';
import 'package:exhuma/exhuma.dart' as exhuma;

class ExhumaExpandableCard extends StatelessWidget {
  final Widget child;

  const ExhumaExpandableCard({
    super.key,
    required this.child,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16.0),
        border: Border.all(color: Theme.of(context).dividerColor),
        color: Theme.of(context).cardColor,
      ),
      padding: const EdgeInsets.all(20.0),
      child: child,
    );
  }
}
